function updateHud(){const c=CLASSES[S.selected],h=S.hero;$('levelLabel').textContent=`0${S.phase+1} / 05`;$('areaLabel').textContent=THEMES[S.phase].name;$('sealLabel').textContent=`Guardiões ${S.seals} / 3`;$('classLabel').textContent=`${c.name} · Nível ${S.level}`;$('hpLabel').textContent=`${S.hp}/${S.maxHp} HP`;$('hpBar').style.width=`${Math.max(0,S.hp/S.maxHp*100)}%`;$('energyBar').style.width=`${S.energy/S.maxEnergy*100}%`;$('xpBar').style.width=`${S.level===15?100:S.xp/xpNeeded()*100}%`;$('xpLabel').textContent=S.level===15?'Nível máximo':`${S.xp}/${xpNeeded()} XP`;$('coinLabel').textContent=`${S.gold} moedas · Equipamento ${S.gear===0?'de treino':`+${S.gear}`}`;$('livesLabel').textContent=`${'♥ '.repeat(S.lives)} · tentativas`;$('powerLabel').textContent=[S.shield>0?`Escudo ${Math.ceil(S.shield)}s`:'',S.jumpBoost>0?`Salto ${Math.ceil(S.jumpBoost)}s`:'',S.stealth>0?'Oculto':''].filter(Boolean).join(' · ');$('abilityLabel').textContent=S.level<3?'Poder no nível 3':skillCooldown>0?`${c.skill}: ${Math.ceil(skillCooldown)}s`:`Ctrl · ${c.skill}`;$('bossHud').hidden=!(boss&&boss.alive&&distance(h.rig.position,boss.rig.position)<25);if(boss)$('bossBar').style.width=`${boss.hp/boss.maxHp*100}%`;$('staminaBar').style.width=`${S.stamina/S.maxStamina*100}%`;$('staminaLabel').textContent=`Stamina ${Math.floor(S.stamina)}/${S.maxStamina} · ${S.flasks} frascos`;$('targetLabel').textContent=validTarget()?`Alvo: ${target.kind==='boss'?'Guardião do Eclipse':target.kind==='sentinel'?'Sentinela':target.kind==='spitter'?'Atirador':'Caçador'} · ${target.hp}/${target.maxHp} HP`:'Q / botão central · travar alvo';$('cameraButton').hidden=mouseCaptured;$('cameraButton').textContent=cameraFallback?'Câmera com mouse ativo':'Ativar câmera do mouse';updatePartnerHud();}
function xpNeeded(){return 60+(S.level-1)*35;}
function awardXP(amount,id){if(S.claimed.has(id))return false;S.claimed.add(id);S.gold+=id==='boss'?100:8+S.phase*2;S.xp+=amount;while(S.level<15&&S.xp>=xpNeeded()){S.xp-=xpNeeded();S.level++;let reward;if([2,7,10,13].includes(S.level)){S.maxHp++;reward='+1 de vida máxima';}else if([4,8,12].includes(S.level)){S.damage++;reward='+1 de dano';}else if(S.level===3)reward=`${CLASSES[S.selected].skill} desbloqueado · Ctrl`;else if(S.level===5)reward='Recarga da esquiva −20%';else if(S.level===9)reward='Recarga da habilidade −20%';else{S.maxEnergy+=20;reward='+20 de energia máxima';}S.hp=Math.min(S.maxHp,S.hp+2);S.energy=S.maxEnergy;S.rewards.push(reward);notify(`Nível ${S.level}! ${reward}`,4);burst(S.hero.rig.position.x,.1,S.hero.rig.position.z,0xffd68a,4);soundNote(650,.25);}if(S.level===15)S.xp=0;return true;}
function startAdventure(){partner=null;Object.assign(S,{mode:'playing',phase:0,level:1,xp:0,gold:0,lives:3,damage:1,gear:0,maxEnergy:100,energy:100,maxStamina:100,stamina:100,flasks:3,claimed:new Set(),rewards:[],elapsed:0});S.hp=S.maxHp=CLASSES[S.selected].hp;S.coop=coopSelected;if(S.coop)partner=createPartner($('partnerClass').value);loadPhase(0);document.body.classList.toggle('coop-active',!!partner);$('overlay').hidden=true;$('playHud').hidden=false;canvas.focus({preventScroll:true});notify('Derrote os três guardiões. E lê placas e abre caminhos.',4);soundNote(400,.2);}
function overlay(title,text,button,mode){S.mode=mode;clearAllInput();if(document.pointerLockElement===canvas)document.exitPointerLock();$('overlay').hidden=false;$('classPicker').hidden=mode!=='menu';$('classHint').hidden=mode!=='menu';$('modePicker').hidden=mode!=='menu';$('coopOptions').hidden=mode!=='menu'||!coopSelected;$('overlayEyebrow').textContent=mode==='paused'?'UM INSTANTE ENTRE BATALHAS':mode==='won'?'O ECLIPSE CHEGOU AO FIM':'A AVENTURA CONTINUA';$('overlayTitle').textContent=title;$('overlayText').textContent=text;$('overlayButton').innerHTML=button+' <span>→</span>';}
function damagePlayer(amount=1,source=null){const h=S.hero;if(S.mode!=='playing'||h.downed||h.invuln>0||h.dodgeTime>0||S.shield>0)return;
 const origin=source?(source.rig?source.rig.position:source.position):null,p=h.rig.position;
 if(isGuarding()&&origin&&new V(Math.sin(h.rig.rotation.y),0,Math.cos(h.rig.rotation.y)).dot(new V(origin.x-p.x,0,origin.z-p.z).normalize())>.15){
  const parry=guardTime<=.18&&source.rig&&source.kind!=='boss',cost=parry?10:22*amount;
  if(S.stamina>=cost){spendStamina(cost);h.invuln=.16;particles(p.x,p.y+1,p.z,0xb4e3e9,8);soundNote(700,.1,'triangle');if(parry){source.stun=1;source.state='recover';source.timer=1;source.warning.visible=false;notify('Parry! Contra-ataque agora.',1.5);}return;}
  S.stamina=0;staminaDelay=.9;guardBreak=1.1;guardHeld=false;notify('Guarda quebrada!');
 }
 healTime=0;pendingAttack=null;h.reviveTarget=null;S.hp-=amount;h.invuln=1.05;shake=.3;particles(p.x,p.y+1,p.z,0xe59c9b);soundNote(120,.18,'sawtooth');if(S.hp<=0)loseLife();}
function loseLife(){if(S.mode!=='playing')return;if(partner){downPlayer();return;}S.lives--;if(S.lives<=0){S.hp=0;overlay('A luz ainda espera.',`Você chegou à fase ${S.phase+1}, nível ${S.level}. Escolha uma classe e tente uma nova aventura.`,'Escolher classe','lost');return;}const h=S.hero;h.rig.position.set(S.checkpoint.x,S.checkpoint.y,S.checkpoint.z);h.vy=0;h.grounded=true;h.invuln=2;h.dodgeTime=0;S.hp=S.maxHp;S.energy=S.maxEnergy;S.stamina=S.maxStamina;S.flasks=3;healTime=0;pendingAttack=null;target=null;clearInput();projectiles.forEach(p=>world.remove(p.mesh));projectiles=[];for(const e of enemies)if(e.alive){e.rig.position.set(e.anchor.x,e.anchor.y,e.anchor.z);e.state='idle';e.timer=0;e.cooldown=1;e.warning.visible=false;if(e.kind==='boss')e.hp=e.maxHp;}camera.position.copy(h.rig.position).add(new V(0,8,12));notify('Retorno ao checkpoint. XP e equipamento preservados.',3);}
function enemyHit(e,damage,source='melee'){if(!e.alive||e.stun>0)return false;const p=S.hero.rig.position,ep=e.rig.position;const toHero=new V(p.x-ep.x,0,p.z-ep.z).normalize(),forward=new V(Math.sin(e.rig.rotation.y),0,Math.cos(e.rig.rotation.y));if(e.kind==='sentinel'&&e.state!=='recover'&&e.state!=='windup'&&source!=='magic'&&source!=='skill'&&source!=='heavy'&&forward.dot(toHero)>.35){particles(ep.x,ep.y+1,ep.z,0xb4ddeb,4);notify('Guarda frontal! Contorne ou ataque após a investida.',1.4);return false;}e.hp-=damage;e.stun=source==='heavy'&&e.kind!=='boss'?.5:.22;if(source==='heavy'&&e.kind!=='boss'){e.state='recover';e.timer=.85;e.warning.visible=false;}e.attackAnim=.2;particles(ep.x,ep.y+1,ep.z,0xefc8a0,8);e.hpFill.scale.x=Math.max(0,e.hp/e.maxHp);soundNote(240,.09,'triangle');if(e.hp<=0){e.alive=false;e.rig.visible=false;if(e.seal){S.seals++;burst(ep.x,ep.y,ep.z,0xffd685,4);notify(`Guardião derrotado · ${S.seals}/3 selos liberados`,3);}partyAwardXP(e.kind==='boss'?250:e.elite?60:25+S.phase*5,e.id);if(e.kind==='boss')notify('O Guardião caiu. O portal final está aberto!',4);}return true;}
function nearestEnemy(range,front=true){let best=null,dist=range;const h=S.hero,p=h.rig.position,fwd=new V(Math.sin(h.rig.rotation.y),0,Math.cos(h.rig.rotation.y));for(const e of enemies){const ep=e.rig.position,d=distance(p,ep);if(!e.alive||Math.abs(p.y-ep.y)>2.3||d>dist)continue;const dot=fwd.dot(new V(ep.x-p.x,0,ep.z-p.z).normalize());if(front&&dot<-.1&&d>2.4)continue;best=e;dist=d;}return best;}
function faceEnemy(e){if(e){const p=S.hero.rig.position;S.hero.rig.rotation.y=Math.atan2(e.rig.position.x-p.x,e.rig.position.z-p.z);}}
function shoot(x,y,z,dir,owner,damage=1,magic=false,speed=18){const color=owner==='enemy'?0xef897f:magic?0xb898ff:0xffd38c;const m=mesh(magic||owner==='enemy'?'sphere':'box',color,x,y,z,magic?.16:.055,magic?.16:.055,magic?.16:.55,world,color);m.rotation.y=Math.atan2(dir.x,dir.z);projectiles.push({mesh:m,dir:dir.clone().normalize(),speed,owner,damage,magic,origin:{x,y,z},player:activeProfile||baseState,life:2.5});}
function attack(heavy=false){if(S.mode!=='playing'||S.hero.downed||S.hero.reviveTarget||attackCooldown>0||pendingAttack||healTime>0||guardBreak>0||S.hero.dodgeTime>0)return;const c=CLASSES[S.selected],cost=S.selected==='mage'?(heavy?18:10):S.selected==='archer'?(heavy?9:5):0,stamina=heavy?32:S.selected==='rogue'?12:18;
 if(S.energy<cost){notify('Sem energia. Aguarde a recuperação.',1);return;}if(!spendStamina(stamina))return;S.energy-=cost;attackCooldown=heavy?Math.max(.9,c.delay*1.8):c.delay;S.hero.attackAnim=heavy?.62:.28;guardHeld=false;faceEnemy(validTarget()?target:nearestEnemy(S.selected==='mage'||S.selected==='archer'?20:3.8));
 if(heavy)pendingAttack={time:.38,heavy:true};else strike(false);}
function strike(heavy){const h=S.hero,p=h.rig.position,ranged=S.selected==='mage'||S.selected==='archer',enemy=validTarget()?target:nearestEnemy(ranged?18:3.2);faceEnemy(enemy);const dir=new V(Math.sin(h.rig.rotation.y),0,Math.cos(h.rig.rotation.y)),damage=(S.damage+S.gear)*(heavy?2:1);
 if(ranged){let aim=dir;if(enemy){const ep=enemy.rig.position;aim=new V(ep.x-p.x,ep.y-p.y,ep.z-p.z).normalize();}shoot(p.x+dir.x*.7,p.y+1.2,p.z+dir.z*.7,aim,'hero',damage,S.selected==='mage',heavy?24:18);}
 else{burst(p.x+dir.x,p.y,p.z+dir.z,heavy?0xffd59e:0xbce4df,heavy?3.2:2.6);for(const e of enemies){if(e.alive&&distance(p,e.rig.position)<(heavy?3.8:S.selected==='warrior'?3.3:2.6)&&Math.abs(p.y-e.rig.position.y)<2.2){const dot=dir.dot(new V(e.rig.position.x-p.x,0,e.rig.position.z-p.z).normalize());if(dot>-.05){const hit=enemyHit(e,damage*(S.critical?2:1),heavy?'heavy':'melee');if(hit&&S.critical){S.critical=false;S.stealth=0;}}}}for(const b of projectiles)if(b.owner==='enemy'&&distance(p,b.mesh.position)<3&&Math.abs(p.y+1-b.mesh.position.y)<2)b.life=0;}
 for(const o of objects)if(o.kind==='crate'&&!o.used&&distance(p,o)<3&&Math.abs(p.y-o.y)<2){o.used=true;o.mesh.visible=false;S.gold+=4;S.energy=Math.min(S.maxEnergy,S.energy+10);particles(o.x,o.y+.5,o.z,0xc5a979);}soundNote(ranged?560:heavy?130:190,.09,'triangle');}
function useSkill(){if(S.mode!=='playing'||S.hero.downed||S.hero.reviveTarget||healTime>0||pendingAttack||guardBreak>0||S.hero.dodgeTime>0||attackCooldown>.1)return;if(S.level<3){notify('Habilidade desbloqueada no nível 3.',2);return;}if(skillCooldown>0)return;const c=CLASSES[S.selected],h=S.hero,p=h.rig.position;if(S.energy<c.cost){notify(`A habilidade precisa de ${c.cost} de energia.`,2);return;}if(!spendStamina(22))return;guardHeld=false;S.energy-=c.cost;attackCooldown=.5;skillCooldown=(S.level>=9?6.4:8);h.attackAnim=.5;const damage=(S.damage+S.gear)*2;
 if(S.selected==='rogue'){S.stealth=4;S.critical=true;h.invuln=.8;notify('Oculto por 4s · próximo golpe crítico');}
 else if(S.selected==='archer'){const e=validTarget()?target:nearestEnemy(20);faceEnemy(e);const angle=h.rig.rotation.y;for(const delta of [-.17,0,.17]){const d=new V(Math.sin(angle+delta),0,Math.cos(angle+delta));shoot(p.x,p.y+1.2,p.z,d,'hero',damage,false,23);}}
 else{const radius=S.selected==='mage'?7:4.8;burst(p.x,p.y,p.z,c.color,radius);for(const e of enemies)if(e.alive&&distance(p,e.rig.position)<radius&&Math.abs(p.y-e.rig.position.y)<3)enemyHit(e,damage,'skill');particles(p.x,p.y+1,p.z,c.color,24);}soundNote(740,.3);}
function moveInput(){if(activeProfile&&activeProfile.padMove&&activeProfile.padMove.lengthSq()>.01){const v=activeProfile.padMove;return new V(v.x*Math.cos(yaw)+v.z*Math.sin(yaw),0,-v.x*Math.sin(yaw)+v.z*Math.cos(yaw));}const x=(keys.has('KeyD')||keys.has('ArrowRight')||touch.has('right')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')||touch.has('left')?1:0),z=(keys.has('KeyS')||keys.has('ArrowDown')||touch.has('back')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')||touch.has('forward')?1:0);return new V(x*Math.cos(yaw)+z*Math.sin(yaw),0,-x*Math.sin(yaw)+z*Math.cos(yaw)).normalize();}
function dodge(){if(S.mode!=='playing'||S.hero.downed||S.hero.reviveTarget||dodgeCooldown>0||pendingAttack||attackCooldown>.12||guardBreak>0||!S.hero.grounded)return;if(!spendStamina(25))return;healTime=0;const h=S.hero;h.dodgeDir=moveInput();if(h.dodgeDir.lengthSq()===0)h.dodgeDir.set(-Math.sin(h.rig.rotation.y),0,-Math.cos(h.rig.rotation.y));h.dodgeTime=.27;h.invuln=Math.max(h.invuln,.3);guardHeld=false;dodgeCooldown=CLASSES[S.selected].dodge*(S.level>=5?.8:1);burst(h.rig.position.x,h.rig.position.y,h.rig.position.z,0x8cdecd,2);soundNote(220,.1);}
function jump(){const h=S.hero;if(S.mode!=='playing'||h.downed||h.reviveTarget||!h.grounded||healTime>0||pendingAttack||guardBreak>0||h.dodgeTime>0)return;if(!spendStamina(8))return;h.vy=S.jumpBoost>0?13:10.5;h.grounded=false;soundNote(330,.08);}
function interact(){if(S.mode!=='playing'||S.hero.downed)return;if(beginRevive())return;const p=S.hero.rig.position;const candidates=objects.filter(o=>!o.used&&o.kind!=='crate'&&o.kind!=='checkpoint'&&distance(p,o)<2.8&&Math.abs(p.y-o.y)<2);candidates.sort((a,b)=>distance(p,a)-distance(p,b));const o=candidates[0];if(!o)return;
 if(o.kind==='sign'){notify('Salte os vãos. E abre pontes. Derrote guardiões; a guarda cede após a investida.',5);return;}
 if(o.kind==='lever'){o.used=true;o.handle.rotation.z=-.5;for(const b of o.bridges){platform(b.x,b.z,b.w,b.d,b.y);mesh('box',0x86b7a8,b.x,b.y+.01,b.z,b.w,.08,.1);}notify('Ponte lateral aberta. Equipamento no alto das ruínas.');}
 if(o.kind==='chest'){if(o.guard.alive){notify('Baú selado. Derrote o sentinela da plataforma.',2);return;}o.used=true;o.mesh.rotation.x=-.18;S.gear=Math.max(S.gear,o.tier);S.hero.weapon.scale.setScalar(1+S.gear*.09);S.gold+=25;S.maxEnergy+=5;S.energy=S.maxEnergy;particles(o.x,o.y+1,o.z,0xffd17e,22);notify(`Equipamento +${S.gear} · +25 moedas · +5 energia máxima`,4);}
 if(o.kind==='shrine'){if(S.gold<30){notify('O santuário precisa de 30 moedas.',2);return;}o.used=true;S.gold-=30;S.hp=S.maxHp;S.energy=S.maxEnergy;S.flasks=3;notify('Santuário: vida e energia restauradas.');burst(o.x,o.y,o.z,0x9af1ca,4);}soundNote(480,.18);}
function blocked(x,z,y,radius=.3){return blocks.some(b=>y<b.h-.1&&Math.abs(x-b.x)<b.w/2+radius&&Math.abs(z-b.z)<b.d/2+radius);}
function updateHero(dt){const h=S.hero,p=h.rig.position;if(h.downed){h.rig.visible=true;h.rig.rotation.z=1.1;return;}h.invuln=Math.max(0,h.invuln-dt);h.dodgeTime=Math.max(0,h.dodgeTime-dt);updateCombat(dt);let dir=moveInput(),speed=CLASSES[S.selected].speed;h.moving=dir.lengthSq()>0;const sprint=(spaceHeld&&spaceTime>.25)||touch.has('sprint');h.sprinting=sprint&&h.moving&&h.grounded&&S.stamina>1&&!isGuarding()&&attackCooldown<=0&&healTime<=0&&guardBreak<=0;if(h.sprinting){speed*=1.55;S.stamina=Math.max(0,S.stamina-18*dt);staminaDelay=.6;}if(isGuarding())speed*=.45;if(attackCooldown>0)speed*=.5;if(healTime>0||guardBreak>0)speed*=.15;if(h.dodgeTime>0){dir=h.dodgeDir;speed=16;}if(h.reviveTarget){speed=0;h.moving=false;}if(validTarget())faceEnemy(target);else if(h.moving)h.rig.rotation.y=Math.atan2(dir.x,dir.z);if(partner){const other=(activeProfile?baseState:partner).hero.rig.position,next={x:p.x+dir.x*speed*dt,z:p.z+dir.z*speed*dt};if(distance(next,other)>20&&distance(next,other)>distance(p,other))speed=0;}if(!blocked(p.x+dir.x*speed*dt,p.z,p.y))p.x+=dir.x*speed*dt;if(!blocked(p.x,p.z+dir.z*speed*dt,p.y))p.z+=dir.z*speed*dt;
 const oldY=p.y;h.vy-=25*dt;p.y+=h.vy*dt;const f=floorAt(p.x,p.z,oldY+.1);if(h.vy<=0&&Number.isFinite(f)&&oldY>=f-.12&&p.y<=f){p.y=f;h.vy=0;h.grounded=true;}else h.grounded=false;if(p.y<-15){loseLife();return;}h.rig.visible=true;if(h.grounded)h.safePosition=p.clone();h.cape.visible=S.stealth<=0||Math.floor(S.stealth*10)%2===0;animateActor(h,animClock,dt);if(isGuarding()){h.leftArm.rotation.x=-1.3;h.rightArm.rotation.x=-.9;}if(healTime>0)h.rightArm.rotation.x=-1.65;if(h.dodgeTime>0){h.rig.rotation.x=-Math.sin(h.dodgeTime/.27*Math.PI)*.95;}else h.rig.rotation.x=0;
 for(const item of items){if(item.taken)continue;item.mesh.rotation.y+=dt;item.mesh.position.y=item.base+Math.sin(animClock*2+item.z)*.15;if(distance(p,item)<1.05&&Math.abs(p.y+.8-item.mesh.position.y)<1.5){item.taken=true;item.mesh.visible=false;if(item.kind==='coin')S.gold+=item.value;else if(item.kind==='shield'){S.shield=10;notify('Escudo ativo por 10s');}else if(item.kind==='jump'){S.jumpBoost=12;notify('Super salto ativo por 12s');}soundNote(630,.05);}}
 for(const o of objects)if(o.kind==='checkpoint'&&!o.used&&distance(p,o)<2&&Math.abs(p.y-o.y)<1){o.used=true;S.checkpoint={x:o.x,y:o.y,z:o.z};S.hp=Math.min(S.maxHp,S.hp+1);burst(o.x,o.y,o.z,0x9ddfea,3);notify('Checkpoint ativado · +1 HP');}
 const downedFriend=partner&&(activeProfile?baseState:partner).hero;const nearby=objects.find(o=>!o.used&&!['crate','checkpoint'].includes(o.kind)&&distance(p,o)<2.8&&Math.abs(p.y-o.y)<2);if(!activeProfile){$('interactionLabel').hidden=!nearby&&!((downedFriend&&downedFriend.downed)&&distance(p,downedFriend.rig.position)<2.8);if(downedFriend&&downedFriend.downed&&distance(p,downedFriend.rig.position)<2.8)$('interactionLabel').textContent='E · Reanimar parceiro (2s)';}if(nearby&&!activeProfile)$('interactionLabel').textContent=`E · ${nearby.kind==='chest'?'Abrir baú':nearby.kind==='shrine'?'Curar · 30 moedas':nearby.kind==='lever'?'Abrir ponte':'Ler placa'}`;
 if(!partner)checkPortal();
}
function checkPortal(){const p=baseState.hero.rig.position; if((distance(p,portal.position)<2.1||(partner&&distance(partner.hero.rig.position,portal.position)<2.1))&&Math.abs(p.y)<2){if(partner&&(partner.hero.downed||baseState.hero.downed||distance(partner.hero.rig.position,portal.position)>8||distance(baseState.hero.rig.position,portal.position)>8)){if(toastTime<=0)notify('Os dois jogadores precisam chegar ao portal.',2);}else if(S.seals<3){if(toastTime<=0)notify(`O portal exige os três guardiões: ${S.seals}/3`,2);}else if(boss&&boss.alive){if(toastTime<=0)notify('Derrote o Guardião do Eclipse para abrir o portal.',2);}else if(S.phase===4){const seconds=Math.floor(S.elapsed);let record='';try{const key=partner?`salto3d-coop-record-${S.selected}-${partner.selected}`:`salto3d-record-${S.selected}`,old=Number(localStorage.getItem(key));if(!old||seconds<old){localStorage.setItem(key,String(seconds));record=' Novo recorde!';}}catch{}overlay('As estrelas voltaram.',`Você venceu os cinco mundos como ${CLASSES[S.selected].name}${partner?' + '+CLASSES[partner.selected].name:''}, nível ${S.level}${partner?' / '+partner.level:''}, em ${Math.floor(seconds/60)}m ${seconds%60}s.${record}`,'Escolher classe','won');}else{loadPhase(S.phase+1);S.hp=S.maxHp;S.energy=S.maxEnergy;notify(`Novo mundo: ${THEMES[S.phase].name}`,4);}}
}

function updateEnemies(dt){for(const e of enemies){if(!e.alive)continue;const victim=party().filter(p=>!p.hero.downed&&p.stealth<=0).sort((a,b)=>distance(a.hero.rig.position,e.rig.position)-distance(b.hero.rig.position,e.rig.position))[0];if(!victim)continue;const hero=victim.hero.rig.position,p=e.rig.position,d=distance(hero,p),height=Math.abs(hero.y-p.y);e.cooldown=Math.max(0,e.cooldown-dt);e.stun=Math.max(0,e.stun-dt);e.timer-=dt;e.moving=false;e.hpBack.visible=e.hpFill.visible=d<18;if(e.stun>0){animateActor(e,animClock,dt);continue;}const notice=d<(e.kind==='boss'?26:16)&&height<2.6&&victim.stealth<=0;
 if(e.state==='windup'){e.warning.visible=true;e.warning.scale.setScalar((e.kind==='boss'?2.5:1.8)*(1+.08*Math.sin(animClock*24)));if(e.timer<=0){e.warning.visible=false;e.attackAnim=.4;if(e.kind==='spitter'){shoot(p.x,p.y+1.3,p.z,e.dir,'enemy',1,true,8+S.phase);e.state='recover';e.timer=.7;}
 else if(e.kind==='boss'&&e.bossPattern%2===0){for(let a=-2;a<=2;a++){const angle=Math.atan2(e.dir.x,e.dir.z)+a*.28;shoot(p.x,p.y+1.7,p.z,new V(Math.sin(angle),0,Math.cos(angle)),'enemy',1,true,10);}e.state='recover';e.timer=1;}
 else{e.state='charge';e.timer=e.kind==='boss'?.65:.4;e.hit=false;}}
 }else if(e.state==='charge'){e.moving=true;const nx=p.x+e.dir.x*dt*(e.kind==='boss'?14:10),nz=p.z+e.dir.z*dt*(e.kind==='boss'?14:10);if(Number.isFinite(floorAt(nx,nz,p.y))&&!blocked(nx,nz,p.y,.5)){p.x=nx;p.z=nz;}if(!e.hit&&distance(hero,p)<(e.kind==='boss'?2.5:1.6)&&height<2){withPlayer(victim,()=>damagePlayer(1,e));e.hit=true;}if(e.timer<=0){e.state='recover';e.timer=e.kind==='boss'?1.1:.85;}}
 else if(e.state==='recover'){if(e.timer<=0){e.state='idle';e.cooldown=e.kind==='boss'?.65:1;}}
 else if(notice){e.rig.rotation.y=Math.atan2(hero.x-p.x,hero.z-p.z);const attackRange=e.kind==='spitter'?12:e.kind==='boss'?12:4.4;if(d<attackRange&&e.cooldown<=0){e.state='windup';e.timer=e.kind==='boss'?(e.hp<e.maxHp/2?.55:.85):e.kind==='spitter'?.85:.65;e.dir.set(hero.x-p.x,0,hero.z-p.z).normalize();e.bossPattern=(e.bossPattern||0)+1;}
 else if(d>(e.kind==='spitter'?7:2.4)){const nx=p.x+Math.sin(e.rig.rotation.y)*e.speed*dt,nz=p.z+Math.cos(e.rig.rotation.y)*e.speed*dt;const floor=floorAt(nx,nz,p.y);if(Number.isFinite(floor)&&Math.abs(floor-p.y)<.3&&!blocked(nx,nz,p.y,.5)){p.x=nx;p.z=nz;e.moving=true;}}
 }else{e.rig.rotation.y+=Math.sin(animClock*.4+e.anchor.z)*dt*.2;}animateActor(e,animClock,dt);}}
function updateProjectiles(dt){for(const b of projectiles){b.life-=dt;const p=b.mesh.position;p.addScaledVector(b.dir,b.speed*dt);if(blocked(p.x,p.z,p.y,.05))b.life=0;if(b.life<=0)continue;if(b.owner==='enemy'){for(const victim of party()){const h=victim.hero.rig.position;if(!victim.hero.downed&&distance(p,h)<.65&&Math.abs(p.y-(h.y+1))<1){withPlayer(victim,()=>damagePlayer(b.damage,{position:b.origin}));b.life=0;break;}}}
 else{for(const e of enemies)if(e.alive&&distance(p,e.rig.position)<(e.kind==='boss'?1.4:.65)&&Math.abs(p.y-(e.rig.position.y+1))<(e.kind==='boss'?2:1)){withPlayer(b.player,()=>enemyHit(e,b.damage,b.magic?'magic':'arrow'));b.life=0;break;}}}projectiles=projectiles.filter(b=>{if(b.life<=0){world.remove(b.mesh);return false;}return true;});}
function updateEffects(dt){for(const e of effects){e.life-=dt;if(e.kind==='particle'){e.mesh.position.addScaledVector(e.velocity,dt);e.velocity.y-=8*dt;e.mesh.scale.setScalar(.065*Math.max(0,e.life/e.max));}else e.mesh.scale.setScalar((1-e.life/e.max)*e.radius+.1);}effects=effects.filter(e=>{if(e.life<=0){world.remove(e.mesh);return false;}return true;});for(const d of decor)if(d.kind==='mote')d.mesh.position.y=d.base+Math.sin(animClock*.5+d.offset)*.35;else d.mesh.rotation.y+=dt*d.speed;}
function cameraUpdate(dt){const p=S.hero.rig.position;const menu=S.mode==='menu';let desired,look;if(menu){const t=animClock*.05;desired=new V(13+Math.sin(t)*2,10,16);look=new V(0,1,-15);}else{
 if(partner){const other=partner.hero.rig.position,mid=p.clone().add(other).multiplyScalar(.5);look=mid.clone().add(new V(0,1.2,0));const range=Math.min(30,cameraDistance+distance(p,other)*.65),horizontal=Math.cos(pitch)*range;desired=new V(mid.x+Math.sin(yaw)*horizontal,mid.y+Math.sin(pitch)*range,mid.z+Math.cos(yaw)*horizontal);}else{if(validTarget()){const ep=target.rig.position,desiredYaw=Math.atan2(p.x-ep.x,p.z-ep.z);yaw+=Math.atan2(Math.sin(desiredYaw-yaw),Math.cos(desiredYaw-yaw))*(1-Math.exp(-dt*5));look=new V(p.x*.7+ep.x*.3,p.y+1.2,p.z*.7+ep.z*.3);}else look=new V(p.x,p.y+1.2,p.z);
 const horizontal=Math.cos(pitch)*cameraDistance;desired=new V(p.x+Math.sin(yaw)*horizontal,p.y+Math.sin(pitch)*cameraDistance,p.z+Math.cos(yaw)*horizontal);}
 }camera.position.lerp(desired,1-Math.exp(-dt*9));if(shake>0){camera.position.x+=(Math.random()-.5)*shake;camera.position.y+=(Math.random()-.5)*shake;}camera.lookAt(look);
 if(lockMarker){lockMarker.visible=S.mode==='playing'&&validTarget();if(lockMarker.visible){lockMarker.position.copy(target.rig.position).add(new V(0,target.kind==='boss'?3.8:2.2,0));lockMarker.quaternion.copy(camera.quaternion);}}
}
let previous=performance.now(),hudClock=0;
function updatePlayer(dt){attackCooldown=Math.max(0,attackCooldown-dt);dodgeCooldown=Math.max(0,dodgeCooldown-dt);skillCooldown=Math.max(0,skillCooldown-dt);S.shield=Math.max(0,S.shield-dt);S.jumpBoost=Math.max(0,S.jumpBoost-dt);S.stealth=Math.max(0,S.stealth-dt);S.energy=Math.min(S.maxEnergy,S.energy+12*dt);if(S.stealth===0)S.critical=false;
 if(!S.hero.downed){if(keys.has('KeyJ')||keys.has('KeyZ')||touch.has('attack')||mouse.has(0))attack(keys.has('ShiftLeft')||keys.has('ShiftRight'));if(keys.has('KeyK')||touch.has('heavy'))attack(true);updateHero(dt);updateRevive(dt);}else{S.hero.rig.visible=true;S.hero.rig.rotation.z=1.1;}}
function frame(now){const dt=Math.min((now-previous)/1000,.04);previous=now;animClock+=S.mode==='paused'?0:dt;pollGamepad(dt);if(S.mode==='playing'){S.elapsed+=dt;updatePlayer(dt);if(partner)withPlayer(partner,()=>updatePlayer(dt));if(S.mode==='playing'){updateEnemies(dt);updateProjectiles(dt);if(partner){updatePartyDowned(dt);if(S.mode==='playing')checkPortal();}}updateEffects(dt);shake=Math.max(0,shake-dt);toastTime-=dt;if(toastTime<=0)$('gameMessage').textContent='';hudClock-=dt;if(hudClock<=0){updateHud();hudClock=.1;}}
 else if(S.mode==='menu'){updateEffects(dt);animateActor(S.hero,animClock,dt);}cameraUpdate(dt);renderer.render(scene,camera);requestAnimationFrame(frame);}
function resize(){const rect=canvas.parentElement.getBoundingClientRect();renderer.setSize(rect.width,rect.height,false);camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas.parentElement);
function pause(){if(S.mode==='playing')overlay('Sou uma pausa, não o fim.','Respire. A aventura espera por você.','Continuar','paused');else if(S.mode==='paused'){S.mode='playing';$('overlay').hidden=true;canvas.focus({preventScroll:true});}}
function spendStamina(amount){if(S.stamina<amount){if(toastTime<=0)notify('Sem stamina. Recue e recupere o fôlego.',1.2);return false;}S.stamina-=amount;staminaDelay=.65;return true;}
function validTarget(){if(target&&(!target.alive||distance(S.hero.rig.position,target.rig.position)>27||Math.abs(S.hero.rig.position.y-target.rig.position.y)>5))target=null;return !!target;}
function toggleTarget(){if(S.mode!=='playing'||S.hero.downed)return;if(validTarget()){target=null;notify('Alvo liberado',1);return;}target=nearestEnemy(22,false);notify(target?'Alvo travado · roda do mouse troca o alvo':'Nenhum alvo próximo',1.5);}
function cycleTarget(direction){if(!validTarget())return;const p=S.hero.rig.position,candidates=enemies.filter(e=>e.alive&&distance(p,e.rig.position)<24&&Math.abs(p.y-e.rig.position.y)<3).sort((a,b)=>Math.atan2(a.rig.position.x-p.x,a.rig.position.z-p.z)-Math.atan2(b.rig.position.x-p.x,b.rig.position.z-p.z));if(candidates.length<2)return;const i=candidates.indexOf(target);target=candidates[(i+direction+candidates.length)%candidates.length];}
function isGuarding(){return guardHeld&&guardBreak<=0&&healTime<=0&&attackCooldown<=0&&S.hero.dodgeTime<=0&&S.hero.grounded;}
function beginGuard(){if(S.mode!=='playing'||S.hero.downed||S.hero.reviveTarget)return;if(!guardHeld)guardTime=0;guardHeld=true;}
function heal(){if(S.mode!=='playing'||S.hero.downed||S.hero.reviveTarget||healTime>0||pendingAttack||attackCooldown>0||S.hero.dodgeTime>0||guardBreak>0)return;if(S.flasks<=0){notify('Sem frascos. O santuário restaura as cargas.',2);return;}if(S.hp>=S.maxHp){notify('Sua vida já está cheia.',1.5);return;}S.flasks--;healTime=.9;guardHeld=false;notify('Bebendo frasco…',.9);}
function updateCombat(dt){if((mouse.has(2)||keys.has('KeyB')||touch.has('guard'))&&!guardHeld&&attackCooldown<=0&&guardBreak<=0)beginGuard();if(spaceHeld)spaceTime+=dt;guardBreak=Math.max(0,guardBreak-dt);staminaDelay=Math.max(0,staminaDelay-dt);if(staminaDelay===0&&!isGuarding())S.stamina=Math.min(S.maxStamina,S.stamina+28*dt);if(guardHeld)guardTime+=dt;
 if(pendingAttack){pendingAttack.time-=dt;if(pendingAttack.time<=0){const heavy=pendingAttack.heavy;pendingAttack=null;strike(heavy);}}
 if(healTime>0){healTime-=dt;if(healTime<=0){healTime=0;S.hp=Math.min(S.maxHp,S.hp+3);burst(S.hero.rig.position.x,S.hero.rig.position.y,S.hero.rig.position.z,0x9df3b9,2);notify('Frasco: +3 HP',1.5);}}
 validTarget();}
function clearInput(){keys.clear();touch.clear();mouse.clear();guardHeld=false;guardTime=0;spaceHeld=false;spaceTime=0;drag=null;document.querySelectorAll('[data-control]').forEach(b=>b.classList.remove('active'));}
function action(name){if(name==='jump')jump();if(name==='attack')attack();if(name==='heavy')attack(true);if(name==='dodge')dodge();if(name==='skill')useSkill();if(name==='interact')interact();if(name==='lock')toggleTarget();if(name==='heal')heal();if(name==='guard')beginGuard();}
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||e.metaKey||e.altKey)return;if(routePartnerKey(e,true))return;const controls=['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyW','KeyA','KeyS','KeyD','KeyJ','KeyZ','KeyK','ShiftLeft','ShiftRight','ControlLeft','ControlRight','KeyQ','KeyL','KeyE','KeyP','KeyF','KeyR','KeyB','Escape'];if(!controls.includes(e.code))return;if(e.target.closest('button,a,summary')&&e.code==='Space')return;if(e.ctrlKey&&!partner&&!['ControlLeft','ControlRight'].includes(e.code))return;e.preventDefault();keys.add(e.code);if(e.repeat)return;if(['KeyJ','KeyZ'].includes(e.code))attack(keys.has('ShiftLeft')||keys.has('ShiftRight'));if(e.code==='KeyK')attack(true);if(e.code==='Space'&&S.mode==='playing'){spaceHeld=true;spaceTime=0;}if(e.code==='KeyF')jump();if(['ControlLeft','ControlRight','KeyL'].includes(e.code))useSkill();if(e.code==='KeyB')beginGuard();if(e.code==='KeyQ')toggleTarget();if(e.code==='KeyR')heal();if(e.code==='KeyE')interact();if(['KeyP','Escape'].includes(e.code))pause();});
document.addEventListener('keyup',e=>{if(routePartnerKey(e,false))return;keys.delete(e.code);if(e.code==='KeyB')guardHeld=false;if(e.code==='Space'){const roll=spaceHeld&&spaceTime<=.25;spaceHeld=false;spaceTime=0;if(roll)dodge();}});
window.addEventListener('blur',()=>{clearAllInput();if(S.mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.mode==='playing')pause();});
for(const b of document.querySelectorAll('[data-control]')){const name=b.dataset.control;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch.add(name);b.classList.add('active');action(name);});const end=()=>{touch.delete(name);b.classList.remove('active');if(name==='guard')guardHeld=false;};b.addEventListener('pointerup',end);b.addEventListener('pointercancel',end);b.addEventListener('lostpointercapture',end);}
function cameraFallbackNotice(){cameraFallback=true;notify('O navegador não capturou o mouse. Mova-o sobre a cena para girar; Esc pausa.',4);}
function captureMouse(){if(S.mode!=='playing'||document.pointerLockElement===canvas)return;canvas.focus({preventScroll:true});if(!canvas.requestPointerLock){cameraFallbackNotice();return;}try{const promise=canvas.requestPointerLock();if(promise&&promise.catch)promise.catch(cameraFallbackNotice);}catch{cameraFallbackNotice();}}
$('cameraButton').addEventListener('click',captureMouse);
document.addEventListener('pointerlockchange',()=>{const was=mouseCaptured;mouseCaptured=document.pointerLockElement===canvas;if(was&&!mouseCaptured){clearAllInput();if(S.mode==='playing')pause();}updateHud();});document.addEventListener('pointerlockerror',cameraFallbackNotice);
canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(S.mode!=='playing')return;e.preventDefault();if(e.pointerType==='touch'){drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);return;}if(e.button===1){toggleTarget();return;}if(!mouseCaptured&&!cameraFallback){captureMouse();return;}mouse.add(e.button);if(e.button===0)attack(keys.has('ShiftLeft')||keys.has('ShiftRight'));if(e.button===2)beginGuard();});
document.addEventListener('pointerup',e=>{mouse.delete(e.button);if(e.button===2)guardHeld=false;if(drag&&drag.id===e.pointerId)drag=null;});canvas.addEventListener('pointercancel',()=>{drag=null;mouse.clear();guardHeld=false;});
function rotateCamera(dx,dy){if(!partner&&validTarget())return;yaw-=dx*.004;pitch=THREE.MathUtils.clamp(pitch+dy*.004,.18,1.08);}
document.addEventListener('mousemove',e=>{if(S.mode==='playing'&&mouseCaptured)rotateCamera(e.movementX,e.movementY);});
canvas.addEventListener('pointermove',e=>{if(S.mode!=='playing')return;if(drag&&drag.id===e.pointerId){rotateCamera(e.clientX-drag.x,e.clientY-drag.y);drag.x=e.clientX;drag.y=e.clientY;}else if(cameraFallback&&e.pointerType==='mouse'&&!mouseCaptured)rotateCamera(e.movementX,e.movementY);});
canvas.addEventListener('wheel',e=>{if(S.mode!=='playing')return;e.preventDefault();if(validTarget())cycleTarget(e.deltaY>=0?1:-1);else cameraDistance=THREE.MathUtils.clamp(cameraDistance+e.deltaY*.008,8,18);},{passive:false});
// Each hero keeps its own combat resources and input. The world advances once.
function party(){return partner?[baseState,partner]:[baseState];}
function freshContext(){return {attackCooldown:0,dodgeCooldown:0,skillCooldown:0,staminaDelay:0,guardHeld:false,guardTime:0,guardBreak:0,spaceHeld:false,spaceTime:0,healTime:0,pendingAttack:null,target:null,keys:new Set(),touch:new Set(),mouse:new Set()};}
function combatContext(){return {attackCooldown,dodgeCooldown,skillCooldown,staminaDelay,guardHeld,guardTime,guardBreak,spaceHeld,spaceTime,healTime,pendingAttack,target,keys,touch,mouse};}
function applyContext(c){({attackCooldown,dodgeCooldown,skillCooldown,staminaDelay,guardHeld,guardTime,guardBreak,spaceHeld,spaceTime,healTime,pendingAttack,target,keys,touch,mouse}=c);}
function withPlayer(profile,fn){const old=activeProfile||baseState;if(!profile||profile===old)return fn();old.context=combatContext();activeProfile=profile===baseState?null:profile;applyContext(profile.context);try{return fn();}finally{profile.context=combatContext();activeProfile=old===baseState?null:old;applyContext(old.context);}}
function createPartner(selected){const p={};for(const key of PLAYER_FIELDS)p[key]=baseState[key];p.selected=selected;p.hp=p.maxHp=CLASSES[selected].hp;p.claimed=new Set();p.rewards=[];p.context=freshContext();p.padPrev=[];p.padMove=new V();return p;}
function clearAllInput(){for(const p of party())withPlayer(p,clearInput);if(partner)partner.padMove.set(0,0,0);}
function partyAwardXP(amount,id){for(const profile of party())withPlayer(profile,()=>{const down=S.hero.downed;awardXP(amount,id);if(down)S.hp=0;});}
function downPlayer(){const h=S.hero;if(h.downed)return;S.hp=0;h.downed=true;h.downTime=20;h.reviveTarget=null;h.dodgeTime=0;h.invuln=0;pendingAttack=null;healTime=0;target=null;if(h.rig.position.y<-5){h.rig.position.copy(h.safePosition||new V(S.checkpoint.x,0,S.checkpoint.z));h.vy=0;}clearInput();notify('Caído! O parceiro tem 20s para reanimar você.',4);}
function beginRevive(){if(!partner)return false;const other=activeProfile?baseState:partner,h=S.hero;if(!other.hero.downed||distance(h.rig.position,other.hero.rig.position)>2.8||Math.abs(h.rig.position.y-other.hero.rig.position.y)>2)return false;if(healTime>0||pendingAttack||attackCooldown>0)return true;h.reviveTarget=other;h.reviveProgress=0;guardHeld=false;notify('Reanimando… fique parado por 2s.',2);return true;}
function updateRevive(dt){const h=S.hero,p=h.reviveTarget;if(!p)return;if(!p.hero.downed||moveInput().lengthSq()>.01||distance(h.rig.position,p.hero.rig.position)>2.8){h.reviveTarget=null;return;}h.reviveProgress+=dt;if(h.reviveProgress>=2){p.hp=Math.max(1,Math.ceil(p.maxHp/2));p.stamina=p.maxStamina;p.hero.downed=false;p.hero.rig.rotation.z=0;p.hero.invuln=1.5;p.hero.downTime=0;h.reviveTarget=null;particles(p.hero.rig.position.x,p.hero.rig.position.y+1,p.hero.rig.position.z,0x9aeece,20);notify('Parceiro reanimado!',3);}}
function updatePartyDowned(dt){if(!partner)return;if(party().every(p=>p.hero.downed)){teamRespawn();return;}for(const p of party())if(p.hero.downed){p.hero.downTime-=dt;if(p.hero.downTime<=0){teamRespawn();return;}}}
function teamRespawn(){S.lives--;if(S.lives<=0){overlay('A equipe caiu.',`Vocês chegaram à fase ${S.phase+1}, níveis ${baseState.level} / ${partner.level}. Escolham suas classes e tentem novamente.`,'Escolher classes','lost');return;}for(const [i,p] of party().entries())withPlayer(p,()=>{const h=S.hero;S.hp=S.maxHp;S.energy=S.maxEnergy;S.stamina=S.maxStamina;S.flasks=3;h.rig.position.set(S.checkpoint.x+(i===0?-1.2:1.2),S.checkpoint.y,S.checkpoint.z);Object.assign(h,{vy:0,grounded:true,invuln:2,dodgeTime:0,downed:false,downTime:0,reviveTarget:null});h.rig.rotation.z=0;h.safePosition=h.rig.position.clone();applyContext(freshContext());});projectiles.forEach(p=>world.remove(p.mesh));projectiles=[];for(const e of enemies)if(e.alive){e.rig.position.set(e.anchor.x,e.anchor.y,e.anchor.z);e.state='idle';e.timer=0;e.cooldown=1;e.warning.visible=false;if(e.kind==='boss')e.hp=e.maxHp;}camera.position.set(S.checkpoint.x,S.checkpoint.y+8,S.checkpoint.z+12);notify('Equipe no checkpoint · progresso preservado.',4);}
function updatePartnerHud(){const hud=$('partnerHud');hud.hidden=!partner;$('coopStatus').hidden=!partner;if(!partner)return;const p=partner;$('partnerClassLabel').textContent=`J2 · ${CLASSES[p.selected].name} · Nv. ${p.level}`;$('partnerHpLabel').textContent=`${p.hp}/${p.maxHp} HP`;$('partnerHpBar').style.width=`${Math.max(0,p.hp/p.maxHp*100)}%`;$('partnerStaminaBar').style.width=`${p.stamina/p.maxStamina*100}%`;$('partnerEnergyBar').style.width=`${p.energy/p.maxEnergy*100}%`;$('partnerXpBar').style.width=`${p.level===15?100:p.xp/(60+(p.level-1)*35)*100}%`;$('partnerResources').textContent=`${p.gold} moedas · Equip. +${p.gear} · ${p.flasks} frascos`;$('partnerStatus').textContent=p.hero.downed?`CAÍDO · ${Math.ceil(p.hero.downTime)}s para reanimar`:p.hero.reviveTarget?'Reanimando parceiro…':`${p.context.target&&p.context.target.alive?'Alvo travado · ':''}${Math.floor(p.stamina)} stamina · ${p.xp} XP`;$('coopStatus').textContent=`COOP LOCAL · J1: mouse/WASD · J2: ${p.padConnected?'controle conectado':'setas + U/O/M/N'} · ${S.lives} tentativas para a equipe`;$('classLabel').textContent=`J1 · ${CLASSES[S.selected].name} · Nv. ${S.level}`;if(S.hero.downed)$('powerLabel').textContent=`J1 caído · ${Math.ceil(S.hero.downTime)}s`;}
const PARTNER_KEYS={ArrowUp:'KeyW',ArrowDown:'KeyS',ArrowLeft:'KeyA',ArrowRight:'KeyD',KeyU:'KeyJ',Numpad1:'KeyJ',KeyO:'KeyK',Numpad2:'KeyK',KeyM:'dodge',Numpad3:'dodge',KeyN:'jump',Numpad0:'jump',KeyH:'KeyB',ControlRight:'KeyB',Numpad4:'KeyB',Enter:'interact',Numpad5:'interact',Delete:'heal',Numpad6:'heal',Backspace:'lock',Numpad7:'lock',ShiftRight:'skill',Numpad8:'skill',End:'sprint',Numpad9:'sprint'};
function routePartnerKey(e,down){if(!partner||!PARTNER_KEYS[e.code])return false;e.preventDefault();const code=PARTNER_KEYS[e.code];withPlayer(partner,()=>{if(!down){keys.delete(code);if(code==='KeyB')guardHeld=false;if(code==='sprint')touch.delete('sprint');return;}if(S.mode!=='playing')return;keys.add(code);if(e.repeat)return;if(code==='KeyJ')attack();if(code==='KeyK')attack(true);if(code==='KeyB')beginGuard();if(code==='sprint')touch.add('sprint');if(['dodge','jump','interact','heal','lock','skill'].includes(code))action(code);});return true;}
function applyGamepad(pad,dt){const now=pad.buttons.map(b=>b.pressed||b.value>.5),prev=partner.padPrev;partner.padPrev=now;partner.padConnected=true;if(now[9]&&!prev[9])pause();if(S.mode!=='playing'){partner.padMove.set(0,0,0);return;}const axis=i=>Math.abs(pad.axes[i]||0)>.2?pad.axes[i]:0;partner.padMove.set(axis(0),0,axis(1));if(partner.padMove.length()>1)partner.padMove.normalize();const rx=axis(2),ry=axis(3);if(rx||ry)rotateCamera(-rx*dt*350,ry*dt*280);
 for(const [index,name] of [[5,'attack'],[7,'heavy'],[4,'guard']]){if(now[index]){touch.add(name);if(!prev[index])action(name);}else{touch.delete(name);if(name==='guard'&&!keys.has('KeyB'))guardHeld=false;}}
 for(const [index,name] of [[0,'interact'],[2,'heal'],[3,'jump'],[6,'skill'],[11,'lock']])if(now[index]&&!prev[index])action(name);
 if(now[1]&&!prev[1]){spaceHeld=true;spaceTime=0;}if(!now[1]&&prev[1]){const roll=spaceTime<=.25;spaceHeld=false;spaceTime=0;if(roll)dodge();}}
function pollGamepad(dt){if(!partner)return;let pad=null;try{pad=navigator.getGamepads?Array.from(navigator.getGamepads()).find(p=>p&&p.connected):null;}catch{};if(pad)withPlayer(partner,()=>applyGamepad(pad,dt));else if(partner.padConnected){partner.padConnected=false;partner.padMove.set(0,0,0);partner.padPrev=[];withPlayer(partner,()=>{touch.clear();spaceHeld=false;guardHeld=false;});}}
for(const button of document.querySelectorAll('[data-mode]'))button.addEventListener('click',()=>{coopSelected=button.dataset.mode==='coop';document.body.classList.toggle('coop-active',coopSelected);document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('coopOptions').hidden=!coopSelected;$('overlayButton').innerHTML=(coopSelected?'Começar em dupla':'Começar aventura')+' <span>→</span>';});

for(const b of document.querySelectorAll('[data-hero]'))b.addEventListener('click',()=>{S.selected=b.dataset.hero;document.querySelectorAll('[data-hero]').forEach(c=>c.setAttribute('aria-pressed',String(c===b)));$('classHint').textContent=`${CLASSES[S.selected].hp} HP · ${CLASSES[S.selected].skill} desbloqueado no nível 3`;if(S.mode==='menu'){world.remove(S.hero.rig);const a=actor(S.selected,CLASSES[S.selected].color);a.rig.position.set(0,0,4);a.rig.rotation.y=Math.PI;S.hero=a;}});
$('overlayButton').addEventListener('click',()=>{if(S.mode==='paused')pause();else if(['won','lost'].includes(S.mode)){overlay('Escolha seu caminho.','Uma nova classe, uma nova aventura.','Começar aventura','menu');$('overlayEyebrow').textContent='UMA NOVA DIMENSÃO';}else startAdventure();});$('pauseButton').addEventListener('click',pause);function soundLabel(){$('soundButton').textContent=sound?'Som ligado':'Som desligado';$('soundButton').setAttribute('aria-pressed',String(sound));}soundLabel();$('soundButton').addEventListener('click',()=>{sound=!sound;soundLabel();try{localStorage.setItem('salto3d-sound',sound?'on':'off');}catch{}if(sound)soundNote(440,.1);});
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();if(S.mode==='playing')pause();notify('A conexão gráfica foi interrompida. Recarregue a página.',60);});
S.hp=S.maxHp=5;loadPhase(0);resize();requestAnimationFrame(frame);
