if(new URLSearchParams(location.search).get('test')==='1')window.__game={S,CLASSES,THEMES,startAdventure,loadPhase,attack,useSkill,dodge,jump,interact,toggleTarget,cycleTarget,heal,beginGuard,awardXP,enemyHit,damagePlayer,loseLife,pause,floorAt,get partner(){return partner;},get coopSelected(){return coopSelected;},setCoop(value){coopSelected=!!value;},withPlayer,partyAwardXP,checkPortal,qaCoop:{party,updatePlayer,updatePartyDowned,updateRevive,pollGamepad,applyGamepad,teamRespawn},get enemies(){return enemies;},get objects(){return objects;},get items(){return items;},get floors(){return floors;},get projectiles(){return projectiles;},get portal(){return portal;},get boss(){return boss;},get renderer(){return renderer;},get camera(){return camera;},qa:{get keys(){return keys;},get touch(){return touch;},get mouse(){return mouse;},updateHero,updateCombat,updateEnemies,updateProjectiles,updateEffects,cameraUpdate,rotateCamera,clearInput,isGuarding,get target(){return target;},get pendingAttack(){return pendingAttack;},get healTime(){return healTime;},get yaw(){return yaw;},get pitch(){return pitch;},get captured(){return mouseCaptured;}},get cooldowns(){return {attack:attackCooldown,dodge:dodgeCooldown,skill:skillCooldown};}};
